// PackConfigCounts is gathered before Begin; clamping is the caller's policy.
type PackConfigCounts struct {
	Reserves int32
}

// PackConfigBlockStorage owns a maximum-sized extent. Do not copy an initialized storage.
type PackConfigBlockStorage struct {
	base       unsafe.Pointer
	allocation []byte
	allocator  TableBlockAllocator
}

func (s *PackConfigBlockStorage) Create(a TableBlockAllocator) bool {
	if s == nil || s.allocation != nil || a.Alloc == nil || a.Free == nil {
		return false
	}
	raw := a.Alloc(PackConfigBlockMaxBytes + 63)
	if int64(len(raw)) < PackConfigBlockMaxBytes+63 {
		if raw != nil {
			a.Free(raw)
		}
		return false
	}
	s.allocation = raw
	s.allocator = a
	offset := (-uintptr(unsafe.Pointer(&raw[0]))) & 63
	s.base = unsafe.Pointer(&raw[offset])
	return true
}
func (s *PackConfigBlockStorage) Destroy() {
	if s != nil && s.allocation != nil {
		s.allocator.Free(s.allocation)
		*s = PackConfigBlockStorage{}
	}
}

// ---- block fill path: begin ----
// PackConfigBlockBegin writes only the prologue and triples, never rows or padding.
// Storage and all counts are checked before any byte of the extent changes.
func PackConfigBlockBegin(b *PackConfigBlock, s *PackConfigBlockStorage, c PackConfigCounts, refusal *TableBlockRefusal) bool {
	if refusal != nil {
		*refusal = TableBlockRefusal{}
	}
	if b == nil {
		return false
	}
	if c.Reserves < 0 || c.Reserves > 3 {
		if refusal != nil {
			*refusal = TableBlockRefusal{Array: "reserves", Count: int64(c.Reserves), Maximum: 3}
		}
		return false
	}
	if s == nil || s.base == nil {
		return false
	}
	p := (*PackConfigBlockProjection)(s.base)
	p.Magic = TableBlockMagic
	p.BuildVersion = BuildVersion
	p.ByteOrder = TableBlockByteOrder
	offset := int64(456)
	offset = (offset + 63) &^ int64(63)
	p.Reserves = TableBlockTriple{OffsetOf: uint64(offset), Count: uint32(c.Reserves), Stride: 108}
	offset += int64(c.Reserves) * 108
	*b = PackConfigBlock{Base: s.base, Projection: p, Bytes: (offset + 63) &^ int64(63)}
	return true
}

func PackConfigBlockBytes(b *PackConfigBlock) int64 {
	if b == nil || b.Projection == nil {
		return 0
	}
	used := int64(456)
	if end := int64(b.Projection.Reserves.OffsetOf) + int64(b.Projection.Reserves.Count)*int64(b.Projection.Reserves.Stride); end > used {
		used = end
	}
	return (used + 63) &^ int64(63)
}

// ---- block fill path: end ----

// Type is this block's descriptors: constant data, so a reflective read costs
// a lookup and not a parse. The row layouts hang off the element column
// rather than taking names of their own, so a walker reaches every record
// through the graph.
func (b *PackConfigBlock) Type() *TableBlockInfo { return &tableBlockRecords[5] }
